html,body { background:var(--appsmith-theme-surfaceColor, #0f172a) !important; margin:0; padding:0; }
.app{width:100%;box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;}
.hdr{color:var(--dark-f1f5f9, var(--appsmith-theme-textStrongColor, #ffffff));font-weight:700;font-size:14px;padding:10px 4px;}
.ag-theme-alpine { --ag-header-background-color:var(--appsmith-theme-surfaceColor, #0f172a); --ag-header-foreground-color:var(--appsmith-theme-textStrongColor, #ffffff); --ag-odd-row-background-color:var(--appsmith-theme-surfaceColor, #0f172a); --ag-background-color:var(--appsmith-theme-cardColor, #1e293b); --ag-row-hover-color:var(--appsmith-theme-hoverSoftColor, #1e293b); --ag-foreground-color:var(--dark-ffffff, var(--appsmith-theme-textColor, #e2e8f0)); --ag-border-color:var(--appsmith-theme-borderSoftColor, #1e293b); --ag-font-size:14px; --ag-row-height:44px; --ag-header-height:48px; border-radius:6px;border:1px solid var(--appsmith-theme-borderSoftColor, #1e293b);overflow:hidden;}
.ag-theme-alpine .ag-row-odd{background-color:var(--appsmith-theme-surfaceColor, #0f172a) !important;}
.ag-theme-alpine .ag-row-even{background-color:var(--appsmith-theme-surfaceAltColor, #1e293b) !important;}
.ag-theme-alpine .ag-row-hover{background-color:var(--appsmith-theme-surfaceHoverColor, #26344b) !important;}
.ag-theme-alpine .ag-header-cell-text{color:var(--appsmith-theme-textStrongColor, #ffffff);}
.detail-link{color:var(--appsmith-theme-linkColor, #60a5fa);cursor:pointer;font-weight:600;}
.pill{display:inline-flex;align-items:center;gap:7px;} .dot{width:8px;height:8px;border-radius:50%;display:inline-block;}
::-webkit-scrollbar{width:10px;height:10px;background:var(--appsmith-theme-surfaceColor, #0f172a);} ::-webkit-scrollbar-thumb{background:var(--dark-1e293b, var(--appsmith-theme-backgroundColor, #1E293A));border-radius:4px;border:2px solid var(--appsmith-theme-surfaceColor, #0f172a);}

